{
  "platform": "ClawHub",
  "uploadPage": "https://clawhub.ai/upload",
  "uploadFormDefaults": {
    "slug": "stockclaw-yingyan",
    "displayName": "stockClaw-yingyan 股票量化助手",
    "version": "1.1.4",
    "tagsText": "latest, stock, quant, openclaw",
    "mit0Accepted": true,
    "updateLog": "1.1.4：openclawCredentials 拆分为 openClaw_api_key / monitor_api_key；HTTP 与 WebSocket 分钥。1.1.3：凭证防重复索要。"
  },
  "uploadFolder": {
    "path": "examples_skill/stockClaw-yingyan",
    "mustInclude": [
      "SKILL.md"
    ],
    "shouldInclude": [
      "reference.md",
