      "CLAWHUB_UPLOAD.md"
    ]
  },
  "openclawCredentials": {
    "user_id": "",
    "openClaw_api_key": "",
    "monitor_api_key": ""
  },
  "runtimeEndpoints": {
    "baseUrl": "https://yingyan.chatface.com",
    "healthUrl": "https://yingyan.chatface.com/api/openclaw/health",
    "demoUrl": "https://yingyan.chatface.com/web/openclaw_demo.html",
    "messageApi": "https://yingyan.chatface.com/api/openclaw/stock/message",
    "stockQueryApi": "https://yingyan.chatface.com/api/openclaw/stock/query",
    "limitUpApi": "https://yingyan.chatface.com/api/openclaw/stock/limit-up",
    "monitorStreamApi": "https://yingyan.chatface.com/api/openclaw/stock/monitor/stream",
    "monitorWsTemplate": "wss://yingyan.chatface.com/ws/monitor/open?apikey={monitor_api_key}&user_id={user_id}"
  },
  "testInputs": {
